export type ProductAvailability = "in_stock" | "preorder" | "made_to_order";

export type Product = {
  slug: string;
  name: string;
  description: string;
  price: number;
  quantity: number; // entero ≥0; unidades disponibles, no qty de carrito
  compareAtPrice?: number;
  images: string[];
  category: string;
  tags: string[];
  inStock: boolean; // derivado: quantity > 0 (legacy JSON con solo inStock: fallback)
  availability?: ProductAvailability;
  featured: boolean;
};

/** Primer src usable. ⛔ `?? ""` — next/image con src vacío tumba prerender. */
export function firstImageSrc(images?: string[] | null): string | undefined {
  const raw = images?.[0];
  if (typeof raw !== "string") return undefined;
  const trimmed = raw.trim();
  return trimmed || undefined;
}

export function priceLabel(price: number, symbol: string): string {
  const hasCents = !Number.isInteger(price);
  const formatted = price.toLocaleString("es-AR", {
    minimumFractionDigits: hasCents ? 2 : 0,
    maximumFractionDigits: 2,
  });
  return `${symbol}${formatted}`;
}

/** Siempre el número, incluso 0. ⛔ copy de “hay stock”. */
export function quantityLabel(quantity: number): string {
  return `${quantity} disponibles`;
}

function asFiniteNumber(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function asString(value: unknown): string {
  return typeof value === "string" ? value : "";
}

function asStringArray(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value.filter(
    (item): item is string => typeof item === "string" && item.trim() !== "",
  );
}

const AVAIL: ReadonlySet<string> = new Set([
  "in_stock",
  "preorder",
  "made_to_order",
]);

export function normalizeProduct(raw: unknown): Product | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const row = raw as Record<string, unknown>;
  const slug = asString(row.slug).trim();
  if (!slug) return null;
  const qtyRaw = row.quantity;
  const quantityIsInt =
    typeof qtyRaw === "number" && Number.isInteger(qtyRaw) && qtyRaw >= 0;
  const quantity = quantityIsInt ? qtyRaw : 0;
  const inStock = quantityIsInt ? quantity > 0 : Boolean(row.inStock);
  const availability =
    typeof row.availability === "string" && AVAIL.has(row.availability)
      ? (row.availability as ProductAvailability)
      : undefined;
  const compareAt = asFiniteNumber(row.compareAtPrice);
  return {
    slug,
    name: asString(row.name),
    description: asString(row.description),
    price: asFiniteNumber(row.price) ?? 0,
    quantity,
    ...(compareAt !== undefined ? { compareAtPrice: compareAt } : {}),
    images: asStringArray(row.images),
    category: asString(row.category),
    tags: asStringArray(row.tags),
    inStock,
    ...(availability ? { availability } : {}),
    featured: Boolean(row.featured),
  };
}

export function normalizeProducts(raw: unknown): Product[] {
  if (!Array.isArray(raw)) return [];
  const out: Product[] = [];
  for (const item of raw) {
    const product = normalizeProduct(item);
    if (product) out.push(product);
  }
  return out;
}

/** Minúsculas y sin tildes, para comparar búsquedas ("Óxido" ≡ "oxido"). #4268 */
function normalizeSearchText(text: string): string {
  return text.normalize("NFD").replace(/\p{M}/gu, "").toLowerCase();
}

/**
 * Filtra por substring sobre `name` y cada `tags[]` (sin tildes ni mayúsculas).
 * Query vacío o solo espacios → mismo array. Sin tokenización: "remera azul"
 * solo matchea si esas palabras aparecen contiguas. #4268
 */
export function filterProducts(products: Product[], query: string | undefined): Product[] {
  const q = normalizeSearchText((query ?? "").trim());
  if (!q) return products;
  return products.filter(
    (product) =>
      normalizeSearchText(product.name).includes(q) ||
      product.tags.some((tag) => normalizeSearchText(tag).includes(q)),
  );
}

/** Orden del listado (#4270). `novedades` = orden del array que entrega el host. */
export const CATALOG_SORTS = ["novedades", "precio_asc", "precio_desc", "nombre"] as const;
export type CatalogSort = (typeof CATALOG_SORTS)[number];

/** Filtros del listado (#4269). El host los parsea de `searchParams` con `parseCatalogFilters`. */
export type CatalogFilters = {
  query?: string; // ?q=  (trim; vacío = sin filtro)
  category?: string; // ?categoria=  (match exacto, sin tildes ni mayúsculas)
  minPrice?: number; // ?precio_min=  (>= 0, inclusivo)
  maxPrice?: number; // ?precio_max=  (>= 0, inclusivo)
  onlyAvailable?: boolean; // ?disponible=1  (product.inStock === true)
  orden?: CatalogSort; // ?orden=  (undefined = novedades = orden del array) #4270
};

function firstParam(value: string | string[] | undefined): string | undefined {
  const raw = Array.isArray(value) ? value[0] : value;
  return typeof raw === "string" ? raw : undefined;
}

/** Número ≥ 0; vacío, no numérico o negativo → undefined (sin filtro). */
function parsePriceParam(value: string | undefined): number | undefined {
  const trimmed = (value ?? "").trim();
  if (!trimmed) return undefined;
  const n = Number(trimmed);
  return Number.isFinite(n) && n >= 0 ? n : undefined;
}

/** Igualdad de categoría: sin tildes ni mayúsculas, sin espacios sobrantes. #4269 */
export function isSameCategory(a: string, b: string): boolean {
  return normalizeSearchText(a.trim()) === normalizeSearchText(b.trim());
}

/** Match exacto tras trim (igual que el resto de la URL); desconocido → undefined. #4270 */
function parseCatalogSort(value: string | undefined): CatalogSort | undefined {
  const trimmed = (value ?? "").trim();
  return (CATALOG_SORTS as readonly string[]).includes(trimmed)
    ? (trimmed as CatalogSort)
    : undefined;
}

/** Parsea la URL del listado. Parámetros repetidos → primer valor. #4269 #4270 */
export function parseCatalogFilters(
  params: Record<string, string | string[] | undefined>,
): CatalogFilters {
  const query = (firstParam(params.q) ?? "").trim();
  const category = (firstParam(params.categoria) ?? "").trim();
  const orden = parseCatalogSort(firstParam(params.orden));
  return {
    ...(query ? { query } : {}),
    ...(category ? { category } : {}),
    minPrice: parsePriceParam(firstParam(params.precio_min)),
    maxPrice: parsePriceParam(firstParam(params.precio_max)),
    onlyAvailable: firstParam(params.disponible) === "1",
    ...(orden ? { orden } : {}),
  };
}

/**
 * Ordena una copia del listado. `undefined` o `novedades` → mismo array (misma
 * referencia). Empates conservan el orden del array. Nunca muta el input. #4270
 */
function sortProducts(products: Product[], orden: CatalogSort | undefined): Product[] {
  if (orden === undefined || orden === "novedades") return products;
  const copy = [...products];
  if (orden === "precio_asc") return copy.sort((a, b) => a.price - b.price);
  if (orden === "precio_desc") return copy.sort((a, b) => b.price - a.price);
  return copy.sort((a, b) => a.name.localeCompare(b.name, "es-AR"));
}

/** Aplica todos los filtros activos (AND) y luego el orden. `precio_min > precio_max` → []. #4269 #4270 */
export function applyCatalogFilters(products: Product[], filters: CatalogFilters): Product[] {
  const category = filters.category?.trim() ? filters.category : undefined;
  const filtered = filterProducts(products, filters.query).filter(
    (product) =>
      (category === undefined || isSameCategory(product.category, category)) &&
      (filters.minPrice === undefined || product.price >= filters.minPrice) &&
      (filters.maxPrice === undefined || product.price <= filters.maxPrice) &&
      (!filters.onlyAvailable || product.inStock === true),
  );
  return sortProducts(filtered, filters.orden);
}

/** Categorías únicas (sin tildes/mayúsculas), no vacías, orden es-AR. #4269 */
export function categoriesOf(products: Product[]): string[] {
  const byKey = new Map<string, string>();
  for (const product of products) {
    const name = product.category.trim();
    if (!name) continue;
    const key = normalizeSearchText(name);
    if (!byKey.has(key)) byKey.set(key, name);
  }
  return [...byKey.values()].sort((a, b) => a.localeCompare(b, "es-AR"));
}

/**
 * Href del listado con los filtros activos (orden fijo q, categoria, precio_min,
 * precio_max, disponible, orden). `overrides` reemplaza campos; `undefined` los quita. #4269 #4270
 */
export function catalogFilterHref(
  filters: CatalogFilters,
  overrides: Partial<CatalogFilters> = {},
): string {
  const next = { ...filters, ...overrides };
  const params = new URLSearchParams();
  if (next.query?.trim()) params.set("q", next.query.trim());
  if (next.category?.trim()) params.set("categoria", next.category.trim());
  if (next.minPrice !== undefined) params.set("precio_min", String(next.minPrice));
  if (next.maxPrice !== undefined) params.set("precio_max", String(next.maxPrice));
  if (next.onlyAvailable) params.set("disponible", "1");
  if (next.orden) params.set("orden", next.orden);
  const qs = params.toString();
  return qs ? `?${qs}` : "?";
}

import { unstable_cache } from "next/cache";
import { draftMode } from "next/headers";
import { eq, sql } from "drizzle-orm";
import { getDb } from "@/db/client";
import { contentEntries } from "@/db/schema";
import { normalizeProducts, type Product } from "./types";
import productsJson from "../../../content/products/products.json";

export type { Product } from "./types";
export { firstImageSrc } from "./types";

async function getContentEntry(
  key: string,
  draft: boolean,
): Promise<unknown | null> {
  const db = getDb();
  if (!db) return null;
  if (draft) {
    const rows = await db
      .select({
        payload: sql<unknown>`COALESCE(${contentEntries.draftData}, ${contentEntries.data})`,
      })
      .from(contentEntries)
      .where(eq(contentEntries.contentKey, key))
      .limit(1);
    return rows[0]?.payload ?? null;
  }
  const rows = await db
    .select()
    .from(contentEntries)
    .where(eq(contentEntries.contentKey, key))
    .limit(1);
  return rows[0]?.data ?? null;
}

async function isDraftEnabled(): Promise<boolean> {
  try {
    const { isEnabled } = await draftMode();
    return isEnabled;
  } catch {
    return false;
  }
}

async function loadProducts(draft: boolean): Promise<Product[]> {
  if (!getDb()) return normalizeProducts(productsJson);
  const data = await getContentEntry("products/products", draft);
  if (!data || !Array.isArray(data)) return [];
  return normalizeProducts(data);
}

const getProductsCached = unstable_cache(
  async () => loadProducts(false),
  ["products/products"],
  { tags: ["content"] },
);

export async function getProducts(): Promise<Product[]> {
  if (await isDraftEnabled()) return loadProducts(true);
  return getProductsCached();
}

export async function getProduct(slug: string): Promise<Product | undefined> {
  const products = await getProducts();
  return products.find((p) => p.slug === slug);
}

export async function getFeaturedProducts(): Promise<Product[]> {
  const products = await getProducts();
  return products.filter((p) => p.featured);
}

export async function getCategories(): Promise<string[]> {
  const products = await getProducts();
  return Array.from(new Set(products.map((p) => p.category)));
}

import Link from "next/link";
import { firstImageSrc, priceLabel, quantityLabel, type Product } from "./types";
import { BLOCK_RADIUS_PRODUCT_CLASS } from "../block-zone/types";

type ProductCardProps = {
  product: Product;
  currencySymbol: string;
};

export function ProductCard({ product, currencySymbol }: ProductCardProps) {
  const image = firstImageSrc(product.images);
  const compare =
    typeof product.compareAtPrice === "number" && product.price < product.compareAtPrice
      ? product.compareAtPrice
      : undefined;

  return (
    <article className={`flex flex-col overflow-hidden ${BLOCK_RADIUS_PRODUCT_CLASS} border border-border bg-card`}>
      <Link href={`/store/${product.slug}`} className="relative block aspect-square overflow-hidden bg-card">
        {image ? (
          <img
            src={image}
            alt={product.name}
            width={800}
            height={800}
            className="size-full object-cover"
          />
        ) : null}
      </Link>
      <div className="flex flex-1 flex-col p-4">
        {product.category ? (
          <p className="text-xs uppercase tracking-wide text-muted-foreground">{product.category}</p>
        ) : null}
        <Link href={`/store/${product.slug}`}>
          <h3 className="mt-1 font-heading text-lg font-medium leading-snug text-foreground">
            {product.name}
          </h3>
        </Link>
        <div className="mt-2 flex items-baseline gap-2">
          <span className="text-lg font-semibold text-primary">
            {priceLabel(product.price, currencySymbol)}
          </span>
          {compare ? (
            <span className="text-sm text-muted-foreground line-through">
              {priceLabel(compare, currencySymbol)}
            </span>
          ) : null}
        </div>
        <p className="mt-1 text-sm text-muted-foreground">
          {quantityLabel(product.quantity)}
        </p>
      </div>
    </article>
  );
}

import { BLOCK_RADIUS_BUTTON_CLASS, BLOCK_RADIUS_CLASS } from "../block-zone/types";
import { ProductCard } from "./product-card";
import {
  applyCatalogFilters,
  CATALOG_SORTS,
  catalogFilterHref,
  categoriesOf,
  isSameCategory,
  type CatalogFilters,
  type CatalogSort,
  type Product,
} from "./types";

type StoreCatalogProps = {
  products: Product[];
  currencySymbol: string;
  /** Filtros activos (el host pasa `parseCatalogFilters(searchParams)`). Opcional: sin él, lista todo. #4268 #4269 */
  filters?: CatalogFilters;
};

const INPUT_CLASS =
  `${BLOCK_RADIUS_BUTTON_CLASS} border border-border bg-card px-4 py-2 text-foreground placeholder:text-muted-foreground`;

const CATALOG_SORT_LABELS: Record<CatalogSort, string> = {
  novedades: "Novedades",
  precio_asc: "Precio: menor a mayor",
  precio_desc: "Precio: mayor a menor",
  nombre: "Nombre (A-Z)",
};

export function StoreCatalog({ products, currencySymbol, filters = {} }: StoreCatalogProps) {
  if (products.length === 0) {
    return null;
  }

  const term = (filters.query ?? "").trim();
  const visible = applyCatalogFilters(products, filters);
  const categories = categoriesOf(products);
  const hasOtherFilters =
    Boolean(filters.category) ||
    filters.minPrice !== undefined ||
    filters.maxPrice !== undefined ||
    Boolean(filters.onlyAvailable);

  return (
    <div className="flex flex-col gap-6">
      {/* Sin JS: method="get" → ?q=&categoria=&precio_min=&precio_max=&disponible=1. Varios campos → botón Aplicar (el Enter no alcanza). */}
      <form role="search" method="get" className="flex flex-col gap-3">
        <input
          type="search"
          name="q"
          defaultValue={filters.query}
          placeholder="Buscá por nombre o etiqueta"
          aria-label="Buscar en la tienda"
          className={`w-full ${INPUT_CLASS}`}
        />
        {filters.category ? <input type="hidden" name="categoria" value={filters.category} /> : null}
        <div className="flex flex-wrap items-end gap-3">
          <label className="flex flex-col gap-1 text-sm text-foreground">
            Precio mínimo
            <input type="number" name="precio_min" min="0" defaultValue={filters.minPrice} className={INPUT_CLASS} />
          </label>
          <label className="flex flex-col gap-1 text-sm text-foreground">
            Precio máximo
            <input type="number" name="precio_max" min="0" defaultValue={filters.maxPrice} className={INPUT_CLASS} />
          </label>
          <label className="flex items-center gap-2 py-2 text-sm text-foreground">
            <input type="checkbox" name="disponible" value="1" defaultChecked={filters.onlyAvailable} />
            Solo disponibles
          </label>
          <label className="flex flex-col gap-1 text-sm text-foreground">
            Ordenar por
            <select name="orden" defaultValue={filters.orden ?? "novedades"} className={INPUT_CLASS}>
              {CATALOG_SORTS.map((sort) => (
                <option key={sort} value={sort}>
                  {CATALOG_SORT_LABELS[sort]}
                </option>
              ))}
            </select>
          </label>
          <button
            type="submit"
            className={`bg-primary px-4 py-2 text-sm font-medium text-primary-foreground ${BLOCK_RADIUS_BUTTON_CLASS}`}
          >
            Aplicar
          </button>
        </div>
      </form>
      <nav aria-label="Categorías">
        <ul className="flex flex-wrap gap-2">
          <li>
            <a
              href={catalogFilterHref(filters, { category: undefined })}
              aria-current={filters.category ? undefined : "page"}
              className="inline-block rounded-full border border-border px-3 py-1 text-sm text-foreground aria-[current=page]:bg-primary aria-[current=page]:text-primary-foreground"
            >
              Todas
            </a>
          </li>
          {categories.map((category) => {
            const active = filters.category ? isSameCategory(category, filters.category) : false;
            return (
              <li key={category}>
                <a
                  href={catalogFilterHref(filters, { category })}
                  aria-current={active ? "page" : undefined}
                  className="inline-block rounded-full border border-border px-3 py-1 text-sm text-foreground aria-[current=page]:bg-primary aria-[current=page]:text-primary-foreground"
                >
                  {category}
                </a>
              </li>
            );
          })}
        </ul>
      </nav>
      {visible.length === 0 ? (
        <div className={`${BLOCK_RADIUS_CLASS} flex flex-col items-start gap-3 border border-border bg-card p-6`}>
          {term ? (
            <>
              <p className="text-foreground">
                No encontramos piezas para “{term}”. Probá con otra palabra o mirá todo el catálogo.
              </p>
              <a href="?" className="text-sm font-medium text-primary underline underline-offset-4">
                Ver todo
              </a>
            </>
          ) : (
            <p className="text-foreground">
              {hasOtherFilters
                ? "No hay piezas con esos filtros. Mirá todo el catálogo."
                : "No hay piezas para mostrar."}
            </p>
          )}
        </div>
      ) : (
        <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
          {visible.map((product) => (
            <ProductCard
              key={product.slug}
              product={product}
              currencySymbol={currencySymbol}
            />
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, type ReactNode } from "react";
import Link from "next/link";
import { firstImageSrc, priceLabel, quantityLabel, type Product } from "./types";
import {
  SECTION_PY_CLASS,
  SECTION_PX_CLASS,
  BLOCK_RADIUS_PRODUCT_CLASS,
  BLOCK_RADIUS_THUMB_CLASS,
} from "../block-zone/types";

type SlotAttrs = { "data-guaso-slot": string } | Record<string, never>;

type ProductDetailProps = {
  product: Product;
  currencySymbol: string;
  storeNav?: string;
  children?: ReactNode;
  // Atributos opacos por zona editable (los calcula el template y los
  // pega el kit con spread). `{}` = no-op. El kit nunca importa `@/lib/*`
  // ni conoce el protocolo de slots.
  imageSlot?: SlotAttrs;
  nameSlot?: SlotAttrs;
  priceSlot?: SlotAttrs;
};

export function ProductDetail({
  product,
  currencySymbol,
  storeNav,
  children,
  imageSlot = {},
  nameSlot = {},
  priceSlot = {},
}: ProductDetailProps) {
  const cover = firstImageSrc(product.images);
  const images = (product.images ?? []).filter(function (img): img is string {
    return typeof img === "string" && img.trim().length !== 0;
  });
  // Destacada = images[0] (#3888). Tap en una miniatura cambia la grande.
  const [selected, setSelected] = useState(0);
  const current = images[Math.min(selected, images.length - 1)] ?? cover;

  return (
    <section className={`mx-auto max-w-[var(--block-container,80rem)] ${SECTION_PX_CLASS} ${SECTION_PY_CLASS}`}>
      <nav className="flex items-center gap-1.5 text-sm text-muted-foreground">
        {storeNav ? (
          <Link href="/store" className="text-muted-foreground">
            {storeNav}
          </Link>
        ) : null}
        {product.category ? (
          <span className="text-foreground/70">{product.category}</span>
        ) : null}
      </nav>

      <div className="mt-8 grid gap-12 md:grid-cols-2">
        <div className="space-y-4">
          <div className={`relative aspect-square overflow-hidden ${BLOCK_RADIUS_PRODUCT_CLASS} bg-card`}>
            {current ? (
              <img
                src={current}
                alt={product.name}
                width={1200}
                height={1200}
                className="size-full object-cover"
                {...imageSlot}
              />
            ) : null}
          </div>
          {images.length > 1 ? (
            <div className="grid grid-cols-4 gap-3">
              {images.map((img, i) => (
                <button
                  key={`${img}-${i}`}
                  type="button"
                  onClick={() => setSelected(i)}
                  aria-label={`Ver foto ${i + 1} de ${product.name}`}
                  aria-current={i === selected}
                  className={`relative aspect-square overflow-hidden ${BLOCK_RADIUS_THUMB_CLASS} bg-card ${
                    i === selected ? "ring-2 ring-primary ring-offset-2" : ""
                  }`}
                >
                  <img
                    src={img}
                    alt={`${product.name} ${i + 1}`}
                    width={240}
                    height={240}
                    className="size-full object-cover"
                  />
                </button>
              ))}
            </div>
          ) : null}
        </div>

        <div className="flex flex-col justify-center">
          {product.category ? (
            <p className="text-sm uppercase tracking-wide text-muted-foreground">
              {product.category}
            </p>
          ) : null}
          <h1
            {...nameSlot}
            className="mt-2 font-heading text-3xl font-semibold text-foreground md:text-4xl"
          >
            {product.name}
          </h1>
          <p
            {...priceSlot}
            className="mt-5 text-3xl font-semibold text-primary"
          >
            {priceLabel(product.price, currencySymbol)}
          </p>
          <p className="mt-2 text-sm text-muted-foreground">
            {quantityLabel(product.quantity)}
          </p>
          {product.description ? (
            <p className="mt-6 max-w-prose leading-relaxed text-muted-foreground">
              {product.description}
            </p>
          ) : null}
          {product.tags?.length ? (
            <div className="mt-5 flex flex-wrap gap-2">
              {product.tags.map((tag) => (
                <span
                  key={tag}
                  className="rounded-full border border-border bg-card px-3 py-1 text-xs font-medium text-foreground"
                >
                  {tag}
                </span>
              ))}
            </div>
          ) : null}
          {children}
        </div>
      </div>
    </section>
  );
}
